def vorlage_bauen(ausgabe_pfad: str = "TN_Vorlage.docx") -> str:
    """Dekodiert den eingebetteten Blob und schreibt die DOCX-Datei."""
    daten = base64.b64decode("".join(_VORLAGE_B64.split()))
    pfad  = os.path.abspath(ausgabe_pfad)
    os.makedirs(os.path.dirname(pfad) if os.path.dirname(pfad) else ".", exist_ok=True)
    with open(pfad, "wb") as datei:
        datei.write(daten)
    return pfad


def hauptprogramm():
    ap = argparse.ArgumentParser(description="STAPCON TN-Vorlage erzeugen")
    ap.add_argument("--out", "-o", default="TN_Vorlage.docx",
                    help="Ausgabepfad (Standard: TN_Vorlage.docx)")
    args = ap.parse_args()
    pfad = vorlage_bauen(args.out)
    print(f"Gespeichert: {pfad}  ({os.path.getsize(pfad):,} Bytes)")


if __name__ == "__main__":
    hauptprogramm()
